<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class PracticeController extends Controller{
 private function find(Request $r,$id){$x=DB::table('practice_placements')->find($id);abort_if(!$x,404);$u=$r->user();$ok=$u->student_id==$x->student_id||$u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('academic_head')||$u->canDo('students.manage')||($u->teacher_id&&$u->teacher_id==$x->supervisor_teacher_id);abort_unless($ok,403);return $x;}
 public function show(Request $r,$practice){$x=$this->find($r,$practice);$student=DB::table('students')->find($x->student_id);$teacher=$x->supervisor_teacher_id?DB::table('teachers')->find($x->supervisor_teacher_id):null;$diary=DB::table('practice_diary_entries')->where('practice_placement_id',$x->id)->orderBy('work_date')->get();$plan=DB::table('practice_plan_items')->where('practice_placement_id',$x->id)->orderBy('sort_order')->get();return view('practice.show',compact('x','student','teacher','diary','plan'));}
 public function update(Request $r,$practice){$x=$this->find($r,$practice);PeriodGuard::writable($x->academic_period_id);abort_if($r->user()->student_id==$x->student_id&&!$r->user()->canDo('students.manage'),403);$d=$r->validate(['individual_task'=>'nullable|string|max:20000','organization_characteristic'=>'nullable|string|max:20000','attestation_notes'=>'nullable|string|max:20000','attestation_grade'=>'nullable|string|max:50']);DB::table('practice_placements')->where('id',$x->id)->update(array_merge($d,['updated_at'=>now()]));return back()->with('success','Документы практики обновлены.');}
 public function report(Request $r,$practice){$x=$this->find($r,$practice);PeriodGuard::writable($x->academic_period_id);abort_unless($r->user()->student_id==$x->student_id,403);$d=$r->validate(['student_report'=>'required|string|max:30000']);DB::table('practice_placements')->where('id',$x->id)->update(['student_report'=>$d['student_report'],'updated_at'=>now()]);return back()->with('success','Отчёт сохранён.');}
 public function plan(Request $r,$practice){$x=$this->find($r,$practice);PeriodGuard::writable($x->academic_period_id);abort_if($r->user()->student_id==$x->student_id&&!$r->user()->canDo('students.manage'),403);$d=$r->validate(['stage'=>'required|string|max:255','task'=>'required|string|max:5000','planned_from'=>'nullable|date','planned_to'=>'nullable|date','sort_order'=>'nullable|integer|min:0']);DB::table('practice_plan_items')->insert(array_merge($d,['practice_placement_id'=>$x->id,'result_status'=>'planned','created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Этап добавлен.');}
 public function print(Request $r,$practice,$form){$x=$this->find($r,$practice);abort_unless(in_array($form,['direction','task','plan','diary','characteristic','attestation','report']),404);$student=DB::table('students')->find($x->student_id);$group=DB::table('study_groups')->find($student->current_group_id);$teacher=$x->supervisor_teacher_id?DB::table('teachers')->find($x->supervisor_teacher_id):null;$diary=DB::table('practice_diary_entries')->where('practice_placement_id',$x->id)->orderBy('work_date')->get();$plan=DB::table('practice_plan_items')->where('practice_placement_id',$x->id)->orderBy('sort_order')->get();return view('practice.print',compact('x','student','group','teacher','diary','plan','form'));}
}